import{_ as a,o as n,c as l,a0 as e}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"XSS 跨站脚本攻击","description":"","frontmatter":{},"headers":[],"relativePath":"loophole/xss.md","filePath":"loophole/xss.md","lastUpdated":1791573371000}'),p={name:"loophole/xss.md"};function o(t,s,r,c,i,d){return n(),l("div",null,[...s[0]||(s[0]=[e(`<h1 id="xss-跨站脚本攻击" tabindex="-1">XSS 跨站脚本攻击 <a class="header-anchor" href="#xss-跨站脚本攻击" aria-label="Permalink to &quot;XSS 跨站脚本攻击&quot;">​</a></h1><p>XSS (Cross Site Scripting)，全称叫做 <code>跨站脚本攻击</code></p><p>一般来说，我们是希望网站运行的东西是来自与本站的。如果网站运行了一个别的网站的东西，那么就产生了一个跨站脚本攻击</p><p>跨站脚本攻击并不是一定要引用一个远程的脚本，也可以是一个内联的脚本，比如经常使用 <code>alert</code> 来探测是否有 XSS 漏洞</p><p>例子中使用的模板引擎为 pug (jade)</p><h2 id="_1-危害" tabindex="-1">1 危害 <a class="header-anchor" href="#_1-危害" aria-label="Permalink to &quot;1 危害&quot;">​</a></h2><ul><li>获取页面数据 (页面内的任何内容和 js 的数据)</li><li>获取 Cookies</li><li>劫持前端逻辑 (比如更改某个按钮的事件)</li><li>发送请求 (将敏感信息发送到攻击者的服务器)</li><li>取决于攻击者的想象力</li></ul><ul><li>偷取网站任意数据</li><li>偷取用户资料</li><li>偷取用户密码和登录态</li><li>欺骗用户</li></ul><h2 id="_2-攻击类型" tabindex="-1">2 攻击类型 <a class="header-anchor" href="#_2-攻击类型" aria-label="Permalink to &quot;2 攻击类型&quot;">​</a></h2><h3 id="_2-1-反射型" tabindex="-1">2.1 反射型 <a class="header-anchor" href="#_2-1-反射型" aria-label="Permalink to &quot;2.1 反射型&quot;">​</a></h3><p>url 参数直接注入。攻击代码直接是由 url 带过来的，而且页面直接显示了这段代码</p><p>我们经常用 url query 来传递数据</p><p>比如 <code>http://www.xxx.com?name=233</code>，如果将 name 的值通过 innerHTML 的方式插入到页面中，那么这里就会有 XSS 漏洞</p><p>如：<code>http://www.xxx.com?name=&lt;script&gt;alert(1)&lt;%2Fscript&gt;</code></p><p>如过 name 的值包含一个脚本，那么打开页面的时候就会运行。如果将这个链接发给别人，别人打开这个链接就能盗取他的信息</p><h3 id="_2-2-存储型" tabindex="-1">2.2 存储型 <a class="header-anchor" href="#_2-2-存储型" aria-label="Permalink to &quot;2.2 存储型&quot;">​</a></h3><p>存储到 DB 后读取时注入</p><p>比如发表评论或者文章的时候，会先存储到数据库。访问的时候，这条代码会从数据库中读取出来，然后显示到用户的页面上</p><p>输入评论的时候可以输入脚本标签，在页面中展示评论的时候，如果未做处理，这么脚本就会在页面中运行</p><p>那么任意一个看到这条评论的用户都可能会受到 XSS 攻击</p><p>如果这个系统有管理端，甚至可以攻击到管理端，获取管理员的信息</p><blockquote><p>反射型的危害略小一些，因为代码直接暴露在 url 中，而存储型很难察觉到，反射型也可以通过生成一个短网址的方式隐藏掉攻击代码</p></blockquote><h2 id="_3-xss-攻击注入点" tabindex="-1">3 XSS 攻击注入点 <a class="header-anchor" href="#_3-xss-攻击注入点" aria-label="Permalink to &quot;3 XSS 攻击注入点&quot;">​</a></h2><h3 id="_3-1-html-节点内容" tabindex="-1">3.1 HTML 节点内容 <a class="header-anchor" href="#_3-1-html-节点内容" aria-label="Permalink to &quot;3.1 HTML 节点内容&quot;">​</a></h3><p>节点内容是动态生成的，展示用户输入的数据</p><p>例如：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">&lt;!-- 通过后端模板插入数据 --&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  #{content}</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">&lt;!-- 如果数据为一个 script 标签，就会运行 --&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_3-2-html-属性" tabindex="-1">3.2 HTML 属性 <a class="header-anchor" href="#_3-2-html-属性" aria-label="Permalink to &quot;3.2 HTML 属性&quot;">​</a></h3><p>节点属性是用户输入的数据，可能会越出属性的范围</p><p>例如：图片的 src 属性，src 是一个动态的值</p><p>src 的内容为 <code>1&quot; onerror=&quot;alert(1)</code> 就会出现下面这种情况</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">img</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;#{image}&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">img</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;1&quot;</span><span style="color:#6F42C1;"> onerror</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;</span><span style="color:#6F42C1;">alert</span><span style="color:#032F62;">(</span><span style="color:#005CC5;">1</span><span style="color:#032F62;">)&quot;</span><span style="color:#24292E;"> /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_3-3-javascript-代码" tabindex="-1">3.3 JavaScript 代码 <a class="header-anchor" href="#_3-3-javascript-代码" aria-label="Permalink to &quot;3.3 JavaScript 代码&quot;">​</a></h3><p>代码中存在由后台注入的变量，里面包含用户输入的信息，会改变代码运行的逻辑</p><p>例如：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#D73A49;">  var</span><span style="color:#24292E;"> data </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;#{data}&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6A737D;">  // var data = &quot;hello&quot;;alert(1);&quot;&quot;;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p>一般前后端分离的项目不会出现这个问题，变量是通过后端模板赋值的，运行时赋值不出现这个问题 (待验证)</p></blockquote><h3 id="_3-4-富文本" tabindex="-1">3.4 富文本 <a class="header-anchor" href="#_3-4-富文本" aria-label="Permalink to &quot;3.4 富文本&quot;">​</a></h3><p>富文本一大段 html 标签，而富文本需要保留 html，html 就会有 XSS 的风险</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#6F42C1;">  alert</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">img</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;1&quot;</span><span style="color:#6F42C1;"> onerror</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;</span><span style="color:#6F42C1;">alert</span><span style="color:#032F62;">(</span><span style="color:#005CC5;">1</span><span style="color:#032F62;">)&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">a</span><span style="color:#6F42C1;"> href</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;javascript:alert(1)&quot;</span><span style="color:#24292E;">&gt;链接&lt;/</span><span style="color:#22863A;">a</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">div</span><span style="color:#6F42C1;"> onclick</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;</span><span style="color:#6F42C1;">alert</span><span style="color:#032F62;">(</span><span style="color:#005CC5;">1</span><span style="color:#032F62;">)&quot;</span><span style="color:#24292E;">&gt;233&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="_4-xss-防御" tabindex="-1">4 XSS 防御 <a class="header-anchor" href="#_4-xss-防御" aria-label="Permalink to &quot;4 XSS 防御&quot;">​</a></h2><h3 id="_4-1-html-节点内容" tabindex="-1">4.1 HTML 节点内容 <a class="header-anchor" href="#_4-1-html-节点内容" aria-label="Permalink to &quot;4.1 HTML 节点内容&quot;">​</a></h3><p>转义标签</p><p>将 <code>&lt;</code> <code>&gt;</code> 转义成 <code>&amp;lt;</code> <code>&amp;gt;</code>，转义的时机可以是在保存到数据库前，或者是在页面展示的时候转义</p><p>转义后 script 标签就会以字符串的形式展示在页面中，而不会运行</p><p>用户输入的内容会原样展示在页面上</p><h3 id="_4-2-html-属性" tabindex="-1">4.2 HTML 属性 <a class="header-anchor" href="#_4-2-html-属性" aria-label="Permalink to &quot;4.2 HTML 属性&quot;">​</a></h3><p>转义引号</p><ul><li>将双引号转义成 <code>&amp;quto;</code></li><li>单引号转义成 <code>&amp;#39;</code></li><li>空格转义成 <code>&amp;#32;</code> (HTML 属性可以不用引号包裹，所以需要转义空格)</li></ul><p>上面的例子就会变成：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">img</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;#{image}&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">img</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;1</span><span style="color:#B31D28;font-style:italic;">&amp;</span><span style="color:#032F62;">quto;</span><span style="color:#005CC5;">&amp;#32;</span><span style="color:#032F62;">onerror=</span><span style="color:#B31D28;font-style:italic;">&amp;</span><span style="color:#032F62;">quto;alert(1)&quot;</span><span style="color:#24292E;"> /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_4-3-javascript-代码" tabindex="-1">4.3 JavaScript 代码 <a class="header-anchor" href="#_4-3-javascript-代码" aria-label="Permalink to &quot;4.3 JavaScript 代码&quot;">​</a></h3><p>转义引号和斜杆</p><ul><li>将 <code>&#39;</code> 转义成 <code>\\\\&#39;</code>，即增加一个转义符</li><li>将 <code>&quot;</code> 转义成 <code>\\\\&quot;</code>，即增加一个转义符</li><li>将 <code>\\</code> 转义成 <code>\\\\</code>，即 <code>str.replace(/\\\\/g, &#39;\\\\\\\\&#39;)</code> 因为输入的斜杆可能会被当作转义符</li></ul><p>这一步通常放在后端逻辑中</p><p>或者使用 JSON 转义，<code>JSON.stringify</code> 会将所以需要转义的内容转义，包括上面提到的引号和斜杆</p><h3 id="_4-4-富文本" tabindex="-1">4.4 富文本 <a class="header-anchor" href="#_4-4-富文本" aria-label="Permalink to &quot;4.4 富文本&quot;">​</a></h3><p>XSS 防御最难处理的就是富文本，富文本是一大段 html</p><p>既然是富文本，就需要保留这些格式，没办法将标签全部转义</p><p>一般的处理方式是过滤，过滤有两种，黑名单和白名单</p><ul><li>黑名单，过滤 script 标签和 onerror 等属性。实现较简单，但是 html 太繁杂，可能过滤不全</li><li>按白名单保留部分标签和属性。白名单是较为安全的方式，不过实现复杂</li></ul><p>目前也有现成库用来处理富文本 <a href="https://github.com/leizongmin/js-xss" target="_blank" rel="noreferrer">https://github.com/leizongmin/js-xss</a></p><h3 id="_4-5-innerhtml" tabindex="-1">4.5 innerHTML <a class="header-anchor" href="#_4-5-innerhtml" aria-label="Permalink to &quot;4.5 innerHTML&quot;">​</a></h3><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Element/innerHTML" target="_blank" rel="noreferrer">innerHTML 文档</a></p><p>用 innerHTML 插入文本到网页中并不罕见。但这有可能成为网站攻击的媒介，从而产生潜在的安全风险问题。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> name</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> &#39;John&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6A737D;">// assuming &#39;el&#39; is an HTML DOM element</span></span>
<span class="line"><span style="color:#24292E;">el.innerHTML </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> name; </span><span style="color:#6A737D;">// harmless in this case</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// ...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">name </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &quot;&lt;script&gt;alert(&#39;I am John in an annoying alert!&#39;)&lt;/script&gt;&quot;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">el.innerHTML </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> name; </span><span style="color:#6A737D;">// harmless in this case</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>尽管这看上去像 <code>cross-site scripting</code> 攻击，结果并不会导致什么。HTML 5 中指定不执行由 innerHTML 插入的 <code>&lt;script&gt;</code> 标签。</p><p>然而，有很多不依赖 <code>&lt;script&gt;</code> 标签去执行 JavaScript 的方式。所以当你使用 innerHTML 去设置你无法控制的字符串时，这仍然是一个安全问题。例如：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> name</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> &quot;&lt;img src=&#39;x&#39; onerror=&#39;alert(1)&#39;&gt;&quot;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">el.innerHTML </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> name; </span><span style="color:#6A737D;">// shows the alert</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>基于这个原因，当插入纯文本时，建议不要使用 innerHTML 。取而代之的是使用 Node.textContent ，它不会把给定的内容解析为 HTML，它仅仅是将原始文本插入给定的位置。</p><h2 id="_5-csp" tabindex="-1">5 CSP <a class="header-anchor" href="#_5-csp" aria-label="Permalink to &quot;5 CSP&quot;">​</a></h2><p>CSP (Content Security Policy)，它是一个 http 的响应头</p><p>全称叫内容安全策略，用于指定哪些内容可执行，即使页面里面有一些注入的内容，它也不会执行</p><p>CSP 是一个可行性比较高的 XSS 防御方案</p><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/CSP" target="_blank" rel="noreferrer">MDN 文档 https://developer.mozilla.org/zh-CN/docs/Web/HTTP/CSP</a></p>`,75)])])}const y=a(p,[["render",o]]);export{h as __pageData,y as default};
